//! 🎛️ The intrinsic shared field records local operations in its original producer action.
use super::*;
use crate::native_decoding::{OriginalEffectProducer,OriginalEffectReply,OriginalEffectReplyComplete};
use std::marker::PhantomData;

type Captured=(Option<(u64,usize,usize,usize)>,Option<crate::OriginalWorkBindingIdentity>);
pub(super) struct Producer<T:RetainedClone+Send+Sync+'static>{identity:Option<(u64,usize,usize,usize)>,work:Option<crate::OriginalWorkBindingIdentity>,value:PhantomData<fn()->T>}
pub(super) enum Operation<'turn,'source,T:RetainedClone+Send+Sync+'static>{
 Capture(RetainedCloneRef<'source,T>),
 Bind(RetainedCloneRef<'source,T>,&'turn mut Option<RetainedCloneBinding>),
 TakeCursor(RetainedCloneRef<'source,T>,&'turn mut RetainedFieldCursor<T>,&'turn mut Option<T>,&'turn mut Option<Result<RetainedCloneStep,ValueError>>),
 CaptureSlot(RetainedCloneRef<'source,T>,&'turn mut crate::NativeSharedSlots<T,SealedShared<T>>,&'turn mut Option<T>,&'turn mut Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>),
 TakeSlot(RetainedCloneRef<'source,T>,&'turn mut crate::NativeSharedSlots<T,SealedShared<T>>,&'turn mut Option<SealedShared<T>>,&'turn mut Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>),
 TakeSlotOutcome(RetainedCloneRef<'source,T>,&'turn mut crate::NativeSharedSlots<T,SealedShared<T>>,&'turn mut Option<crate::native_decoding::NativeReceivingEffectOutcome<crate::OriginalRetirementFailure>>,&'turn mut Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>),
 AcknowledgeSlotOutcome(RetainedCloneRef<'source,T>,&'turn mut Option<crate::native_decoding::NativeReceivingEffectOutcome<crate::OriginalRetirementFailure>>),
 CloseStart(RetainedCloneRef<'source,T>,&'turn mut RetainedFieldCursor<T>),
 Phase(RetainedCloneRef<'source,T>,&'turn mut u8,u8),
}
impl<T:RetainedClone+Send+Sync+'static> Producer<T>{pub(super) fn new()->Self{Self{identity:None,work:None,value:PhantomData}}pub(super) fn identity(&self)->Option<(u64,usize,usize,usize)>{self.identity}pub(super) fn capture_demand()->RetirementDemand{fixed(std::mem::size_of::<Option<(u64,usize,usize,usize)>>()+std::mem::size_of::<Option<crate::OriginalWorkBindingIdentity>>())}pub(super) fn matches_effect(&self,effect:&crate::RetainedAllocationEffect<'_>)->bool{self.work.is_some_and(|binding|binding.matches_effect(effect))}}
impl<T:RetainedClone+Send+Sync+'static> crate::retirement::RetireOwned for Producer<T>{type RetirementCursor=<Captured as crate::retirement::RetireOwned>::RetirementCursor;fn retirement_seed(self)->Self::RetirementCursor{crate::retirement::RetireOwned::retirement_seed((self.identity,self.work))}fn controlled_retirement_supported()->bool{<Captured as crate::retirement::RetireOwned>::controlled_retirement_supported()}}
fn record<'reply,E:Into<OriginalReceivingPrimary>>(inner:&mut Option<Result<RetainedCloneStep,E>>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{if inner.is_none(){return Ok(reply.pending())}let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,E>>>();if effect.remaining_work_units()?<1||effect.grant().maximum_copy_bytes<copy{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"field nested reply lacks its original grant"))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"field nested reply exceeded its original work").into())))}let result=inner.take().expect("original field child reply selected");Ok(reply.complete(match result{Ok(step)=>{let mut p=step.progress();p.copied_items=p.copied_items.max(1);p.copied_bytes=p.copied_bytes.checked_add(copy).expect("admitted field reply extent");Ok(RetainedCloneStep::Progress(p))},Err(error)=>{let mut error:OriginalReceivingPrimary=error.into();error.progress.copied_items=error.progress.copied_items.max(1);error.progress.copied_bytes=error.progress.copied_bytes.checked_add(copy).expect("admitted field failure extent");Err(error)}}))}
impl<T:RetainedClone+Send+Sync+'static> OriginalEffectProducer for Producer<T>{
 type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'turn,'source>=Operation<'turn,'source,T> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,context:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{let input=match context{Operation::Capture(input)|Operation::Bind(input,_)|Operation::TakeCursor(input,..)|Operation::CaptureSlot(input,..)|Operation::TakeSlot(input,..)|Operation::TakeSlotOutcome(input,..)|Operation::AcknowledgeSlotOutcome(input,..)|Operation::CloseStart(input,_)|Operation::Phase(input,..)=>*input};let actual=input.reference_identity();match(self.identity,context){(None,Operation::Capture(_))=>Ok(()),(Some(expected),_)if expected==actual=>Ok(()),_=>Err(ValueError::invariant("original shared field source changed"))}}
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn receive<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{if self.work.is_some()&&!self.matches_effect(effect){return Ok(reply.complete(Err(ValueError::invariant("field action changed its original Work owner").into())))}match context{
  Operation::Capture(input)=>{if effect.work_source_turn().is_none(){return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"field capture requires its actual original Source").into())))}let binding=crate::OriginalWorkBindingIdentity::from_effect(effect);if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"field source capture exceeded original work").into())))}self.identity=Some(input.reference_identity());self.work=Some(binding);Ok(reply.complete(Ok(RetainedCloneStep::Progress(receipt(Self::capture_demand())))))},
  Operation::Bind(input,binding)=>{let turn=input.bind(binding,effect);Ok(reply.complete(turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)))},
  Operation::TakeCursor(_,cursor,output,inner)=>{let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,ValueError>>>();let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"field reply lacks reserved work"))?;let grant=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g};{let mut child=effect.reborrow(grant,remaining)?;let nested=OriginalEffectReply::borrow(inner)?;drop(cursor.take(output,&mut child,nested)?)}record(inner,effect,reply)},
  Operation::CaptureSlot(_,slots,input,inner)=>{let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>();let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"field reply lacks reserved work"))?;let grant=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g};{let mut child=effect.reborrow(grant,remaining)?;let nested=OriginalEffectReply::borrow(inner)?;drop(slots.capture(input,&mut child,nested)?)}record(inner,effect,reply)},
  Operation::TakeSlot(_,slots,output,inner)=>{let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>();let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"field reply lacks reserved work"))?;let grant=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g};{let mut child=effect.reborrow(grant,remaining)?;let nested=OriginalEffectReply::borrow(inner)?;drop(slots.take(output,&mut child,nested)?)}record(inner,effect,reply)},
  Operation::TakeSlotOutcome(_,slots,output,inner)=>{let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>();let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"field reply lacks reserved work"))?;let grant=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g};{let mut child=effect.reborrow(grant,remaining)?;let nested=OriginalEffectReply::borrow(inner)?;drop(slots.take_advance_result(output,&mut child,nested)?)}record(inner,effect,reply)},
  Operation::AcknowledgeSlotOutcome(_,outcome)=>crate::native_decoding::NativeReceivingEffect::<crate::OriginalRetirementFailure>::acknowledge_success_into(outcome,effect,reply),
  Operation::CloseStart(_,cursor)=>{let turn=cursor.begin_close_paid(effect);Ok(reply.complete(turn.result.map(RetainedCloneStep::Progress).map_err(Into::into)))},
  Operation::Phase(_,phase,next)=>{if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"field phase exceeded original work").into())))}**phase=*next;Ok(reply.complete(Ok(RetainedCloneStep::Progress(receipt(fixed(std::mem::size_of::<u8>()))))))},
 }}
 fn recover<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{if self.work.is_some()&&!self.matches_effect(effect){return Ok(reply.complete(Err(ValueError::invariant("field action changed its original Work owner").into())))}match context{
  Operation::TakeCursor(_,cursor,output,inner)=>{if inner.is_none(){let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,ValueError>>>();let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"field reply lacks reserved work"))?;let grant=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g};let mut child=effect.reborrow(grant,remaining)?;let nested=OriginalEffectReply::borrow(inner)?;drop(cursor.recover_take(output,&mut child,nested)?)}record(inner,effect,reply)},
  Operation::CaptureSlot(_,slots,input,inner)=>{if inner.is_none(){let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>();let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"field reply lacks reserved work"))?;let grant=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g};let mut child=effect.reborrow(grant,remaining)?;let nested=OriginalEffectReply::borrow(inner)?;drop(slots.recover_capture(input,&mut child,nested)?)}record(inner,effect,reply)},
  Operation::TakeSlot(_,slots,output,inner)=>{if inner.is_none(){let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>();let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"field reply lacks reserved work"))?;let grant=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g};let mut child=effect.reborrow(grant,remaining)?;let nested=OriginalEffectReply::borrow(inner)?;drop(slots.recover_take(output,&mut child,nested)?)}record(inner,effect,reply)},
  Operation::TakeSlotOutcome(_,slots,output,inner)=>{if inner.is_none(){let copy=2*std::mem::size_of::<Option<Result<RetainedCloneStep,crate::OriginalRetirementFailure>>>();let g=effect.grant();let remaining=effect.remaining_work_units()?.checked_sub(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"field reply lacks reserved work"))?;let grant=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(copy).ok_or_else(invalid)?,..g};let mut child=effect.reborrow(grant,remaining)?;let nested=OriginalEffectReply::borrow(inner)?;drop(slots.recover_take_advance_result(output,&mut child,nested)?)}record(inner,effect,reply)},
  Operation::AcknowledgeSlotOutcome(_,outcome)=>crate::native_decoding::NativeReceivingEffect::<crate::OriginalRetirementFailure>::acknowledge_success_into(outcome,effect,reply),
  _=>Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"field local operation has no unresolved callback")),
 }}
}
